/* Resolves the compiled design-system namespace without hard-coding its name.
   The compiler picks the namespace from the project title, so a card that
   hard-codes it breaks if the project is renamed. Usage:

     <script src="../../_ds_bundle.js"></script>
     <script src="../../ds-mount.js"></script>
     <script type="text/babel">
       const { Button, Badge } = dsFind('Button', 'Badge');
     </script>

   `_ds_bundle.js` is generated by the design-system compiler, which only runs
   once the project's file type is set to Design System. Until then dsFind()
   explains itself in the page rather than throwing into a blank card. */

function dsBundleMissingNotice(names) {
    const el = document.getElementById('root') || document.body;
    el.innerHTML =
        '<div style="font-family:var(--font-sans);max-width:560px;' +
        'border:1px solid var(--status-pending-border);background:var(--status-pending-bg);' +
        'border-radius:var(--radius-xl);padding:14px 16px">' +
        '<p style="margin:0 0 6px;font-size:13px;font-weight:600;color:var(--status-pending-deep)">' +
        'Component bundle not built yet</p>' +
        '<p style="margin:0;font-size:13px;line-height:1.55;color:var(--status-pending-deep)">' +
        'This card mounts <code style="font-family:var(--font-mono)">' +
        names.join('</code>, <code style="font-family:var(--font-mono)">') +
        '</code> from <code style="font-family:var(--font-mono)">_ds_bundle.js</code>, ' +
        'which the compiler generates once this project\u2019s file type is set to ' +
        '<strong>Design System</strong> in the Share menu. The foundation cards under ' +
        '<code style="font-family:var(--font-mono)">guidelines/</code> need only ' +
        '<code style="font-family:var(--font-mono)">styles.css</code> and render now.</p>' +
        '</div>';
}

window.dsFind = function dsFind(...names) {
    /* Reads are wrapped: `window` can hold cross-origin frame references whose
       property access throws SecurityError, which would kill the whole card. */
    const hit = Object.keys(window)
        .map((k) => {
            try {
                return window[k];
            } catch {
                return null;
            }
        })
        .find((v) => {
            try {
                return (
                    v &&
                    typeof v === 'object' &&
                    names.every((n) => typeof v[n] === 'function')
                );
            } catch {
                return false;
            }
        });
    if (!hit) {
        dsBundleMissingNotice(names);
        throw new Error(
            'design-system bundle not found, or it does not export: ' +
                names.join(', '),
        );
    }
    return hit;
};
